		\{profiles.stream().skip(1)
			.map(profile -> 
				"\n" +
				"\t\t\t" + profile.id + "\n" +
				(profile.activation != null ? 
					"\t\t\t\n" +
					"\t\t\t\t" + profile.activation.activeByDefault + "\n" +
					"\t\t\t\n" : "") +
				"\t\t\t\n" +
				profile.properties.entrySet().stream()
					.map(entry -> "\t\t\t\t<" + entry.getKey() + ">" + entry.getValue() + "</" + entry.getKey() + ">")
					.collect(java.util.stream.Collectors.joining("\n")) +
				"\n\t\t\t\n" +
				"\t\t")
			.collect(java.util.stream.Collectors.joining("\n\t\t"))}





		\{dependencies.stream()
			.map(dep -> 
				"\n" +
				"\t\t\t" + dep.groupId + "\n" +
				"\t\t\t" + dep.artifactId + "\n" +
				"\t\t\t" + dep.version + "\n" +
				(dep.scope != null ? "\t\t\t" + dep.scope + "\n" : "") +
				(dep.optional != null ? "\t\t\t" + dep.optional + "\n" : "") +
				(dep.exclusions != null && !dep.exclusions.isEmpty() ?
					"\t\t\t\n" +
					dep.exclusions.stream()
						.map(excl -> 
							"\t\t\t\t\n" +
							"\t\t\t\t\t" + excl.groupId + "\n" +
							"\t\t\t\t\t" + excl.artifactId + "\n" +
							"\t\t\t\t")
						.collect(java.util.stream.Collectors.joining("\n")) +
					"\n\t\t\t\n" : "") +
				"\t\t")
			.collect(java.util.stream.Collectors.joining("\n\t\t"))}




		\{repositories.stream()
			.map(repo -> 
				"\n" +
				"\t\t\t" + repo.id + "\n" +
				"\t\t\t" + repo.name + "\n" +
				"\t\t\t" + repo.url + "\n" +
				(repo.releases != null ? 
					"\t\t\t\n" +
					"\t\t\t\t" + repo.releases.enabled + "\n" +
					"\t\t\t\n" : "") +
				(repo.snapshots != null ? 
					"\t\t\t\n" +
					"\t\t\t\t" + repo.snapshots.enabled + "\n" +
					"\t\t\t\n" : "") +
				"\t\t")
			.collect(java.util.stream.Collectors.joining("\n\t\t"))}



	\{generateReporting ? 
		"\n" +
		"\t\t\n" +
		reportingPlugins.stream()
			.map(plugin -> 
				"\t\t\t\n" +
				"\t\t\t\t" + plugin.groupId + "\n" +
				"\t\t\t\t" + plugin.artifactId + "\n" +
				"\t\t\t\t" + plugin.version + "\n" +
				"\t\t\t")
			.collect(java.util.stream.Collectors.joining("\n")) +
		"\n\t\t\n" +
		"\t" : ""}



		\{organization.name}
		\{organization.url}



		\{developers.stream()
			.map(dev -> 
				"\n" +
				"\t\t\t" + dev.id + "\n" +
				"\t\t\t" + dev.name + "\n" +
				"\t\t\t" + dev.email + "\n" +
				"\t\t\t\n" +
				dev.roles.stream()
					.map(role -> "\t\t\t\t\t" + role + "")
					.collect(java.util.stream.Collectors.joining("\n")) +
				"\n\t\t\t\t\n" +
				"\t\t\t")
			.collect(java.util.stream.Collectors.joining("\n\t\t"))}




		\{issueManagement.system}
		\{issueManagement.url}



		\{ciManagement.system}
		\{ciManagement.url}

			\{ciManagement.notifiers.stream()
				.map(notifier -> 
					"\n" +
					"\t\t\t\t" + notifier.type + "\n" +
					"\t\t\t\t" + notifier.sendOnError + "\n" +
					"\t\t\t\t" + notifier.sendOnFailure + "\n" +
					"\t\t\t\t" + notifier.sendOnSuccess + "\n" +
					"\t\t\t\t" + notifier.address + "\n" +
					"\t\t\t")
				.collect(java.util.stream.Collectors.joining("\n\t\t\t"))}





